import{_ as o,l as h,o as t,c as r,v as p,p as s,x as l,d as n,i as m,S as E,b as a}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"AlphaSchema 领域本体","description":"","frontmatter":{"title":"AlphaSchema 领域本体","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/alphaschema-ontology.md","filePath":"quant/alphaschema-ontology.md","lastUpdated":1789023840000}'),A={name:"quant/alphaschema-ontology.md"};function c(d,e,u,B,L,f){const i=h("Mermaid");return t(),r("div",null,[e[1]||(e[1]=p('<h1 id="alphaschema-领域本体" tabindex="-1">AlphaSchema 领域本体 <a class="header-anchor" href="#alphaschema-领域本体" aria-label="Permalink to &quot;AlphaSchema 领域本体&quot;">​</a></h1><div class="epigraph"><p>搜索的对象不应是代码或公式，而是先于实现的交易语义计划；计划由事件、情境、质量约束、方向与输出五元组构成。</p><footer>—— Yi, Yang, Jin, Li and Li, AlphaSchema: Exploring the Space of Trading Semantics for LLM-Based Alpha Mining, arXiv:2607.26642</footer></div><p>Alpha-GPT 让模型在对话里隐含地选搜索空间；Hubble 在 DSL 树上搜；XAlpha 在假设与代码之间演化。AlphaSchema（Yi 等人，X-Tech / Monash / 清华交叉信息院等，arXiv:2607.26642）把空间本身造出来：每个候选先是一个语义计划 \\(p=(e,c,Q,d,o)\\)，再由 LLM 翻译成可执行因子。探索与实现解耦。奖励记在计划上，用替代模型（文中 LightGBM）在语义特征上打分，配额选择在全局探索、替代利用与局部变异之间分配有限的实现与回测预算。这是领域本体加贝叶斯式搜索，不是把交易语义当成操纵对手盘的剧本。公开实验在 A 股，并报告不同 LLM 实现同一计划时预测质量相近——作者读成「挖掘质量对模型选择大体稳健」。读幅度时仍要用 Hou–Xue–Zhang 的加权手续与 McLean–Pontiff 的发表后折扣：语义计划可以很像一篇论文的摘要，因而也很容易拥挤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>许多 LLM 挖掘把「构造因子」和「决定下一步搜什么」都交给同一个代理。候选空间由提示、记忆轨迹和模型偏好隐性塑形，多样性不可测，覆盖不可控，轨迹难复现，成本绑在前沿模型的采样上。公式化与进化方法在实现空间里组合算子，驱动信号是数学适应度，不是可陈述的交易假设。需要一种表示：在写代码之前就能说清「捕捉什么事件、在什么情境、用什么确认、赌延续还是反转、输出什么形态」，并把搜索定义在该表示上。</p><p>本体在这里是工作定义，不是形而上学的市场分类学。作者不声称五元组穷尽机制，只声称它足够表达常见因子构造维度，使计划空间 \\(\\mathcal{P}\\) 可配置、可抽样、可学习。词汇表 \\(\\mathcal{V}_E,\\mathcal{V}_C,\\mathcal{V}_Q,\\mathcal{V}_D,\\mathcal{V}_O\\) 是超参：词表写成「突破、放量、波动压缩」，搜索就会往技术分析靠；不加「盈利意外」一类事件，基本面机制根本不在空间里。本体先于模型。</p><h3 id="计划不是因子-实现是随机映射" tabindex="-1">计划不是因子，实现是随机映射 <a class="header-anchor" href="#计划不是因子-实现是随机映射" aria-label="Permalink to &quot;计划不是因子，实现是随机映射&quot;">​</a></h3><p>形式化：\\(p\\in\\mathcal{P}\\) 是语义计划，\\(\\Gamma:\\mathcal{P}\\to\\Delta(\\mathcal{F})\\) 是实现过程，把计划映到可执行因子的分布。目标是 \\(\\max_p \\mathbb{E}_{f\\sim\\Gamma(p)}[\\mathcal{J}(f)]\\)。同一计划可用不同算子、窗口、函数形式实现，一次回测只是该分布的一个样本。因此奖励记在计划上、用多次实现或替代模型平滑，而不是把一次幸运代码的夏普当成该语义为真。这直接对抗「换一个随机种子又一个新因子」的幻觉。</p><p><span class="marginnote">若词表从已发表异常的摘要里长出来，本体就是拥挤地图。应把 McLean–Pontiff 清单上的预测变量标成已知点，搜索时要么当负例，要么要求计划在五元组上与它们的距离足够远。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每轮：提出并选择计划（全局抽样、局部变异、配额分配）→ LLM 实现为代码 → 执行、泄漏、回测门 → 计划-奖励写入缓冲 → 更新语义打分器。打分器在计划的离散特征上回归 \\(\\mathcal{J}\\)，对尚未实现的大候选池先打分，再花预算去实现。配额把有限次数分给：结构新颖（覆盖未知区域）、替代高分（利用）、强计划邻域的变异（局部改进）。关联反馈与计划而非与算子，是为了学习「哪些交易语义值得探」，而不是「哪棵树碰巧高」。</p><p>五维的直观分工：</p><ul><li><strong>Event</strong>：被捕捉的市场现象，如突破、放量、波动压缩。</li><li><strong>Context</strong>：解释该事件的参照，如近期极值、VWAP 区域、波动体制、截面分位。</li><li><strong>Qualities</strong>：确认或过滤，如成交量确认、多周期一致、去极值。</li><li><strong>Direction</strong>：与未来收益的假设关系，延续、反转、区间震荡。</li><li><strong>Output</strong>：可交易形态，连续分数、事件衰减、截面排序。</li></ul><p>实现后的因子仍须过数据合同与泄漏规则，再进回测。论文强调守卫式回测：计划、生成代码、校验状态与结果一并落盘。代码仓库在论文致谢中公开核心流程；以 arXiv 与仓库为准，附属公司新闻稿不是方法来源。</p><h3 id="替代模型让-llm-从搜索决策里退出来" tabindex="-1">替代模型让 LLM 从搜索决策里退出来 <a class="header-anchor" href="#替代模型让-llm-从搜索决策里退出来" aria-label="Permalink to &quot;替代模型让 LLM 从搜索决策里退出来&quot;">​</a></h3><p>若每一步「搜什么」都要模型采样，探索政策不可复现，也随供应商变。替代模型把决策变成：在已知 \\((p,\\text{reward})\\) 上拟合，对候选 \\(p\\) 打分，再用配额掺入随机探索。LLM 的角色收缩为实现器 \\(\\Gamma\\)，而不是规划器。作者报告同一计划换不同 LLM 实现，预测质量可比，支持「瓶颈在计划不在文风」这一读法。工程上仍应固定实现器版本做主结果，换模型只当敏感性，避免把实现噪声当成新发现。</p><p><span class="marginnote">LightGBM 在离散语义特征上过拟合同样会发生：计划空间若比回测次数大得多，替代器会记住噪声奖励。配额里必须保留真正的结构探索，不能把预算全给当前高分区域。这与金融里「只交易正在赚钱的因子」是同一错误。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>解耦之后，多样性可在计划空间度量：事件-情境组合的覆盖、与已评估计划的汉明或集合距离。覆盖不足时提高探索配额；高奖励区域出现时提高利用与变异。这比在公式树上做编辑距离更接近「机制是否重复」。拥挤衰减的控制也应发生在这一层：与已部署因子对应的计划邻域降权，而不是等代码相关到 0.9 再丢。</p><p>奖励 \\(\\mathcal{J}\\) 若只用样本内 IC，本体搜索会高效找到拥挤且高 t 的技术语义。\\(\\mathcal{J}\\) 应含换手惩罚、覆盖、与库的相关、以及验证段表现，最好再含成本情景，见<a href="/quant/cost-mc-sensitivity">费用 MC</a>。否则五元组只是给过拟合加了一层可解释的外衣。Hou–Xue–Zhang 的摩擦类异常，许多可以写成「低流动性事件 + 小盘情境 + 反转方向」；词表与奖励若不禁这类计划，复制失败会在语义层重演。</p><h3 id="本体是可审计的中间语言" tabindex="-1">本体是可审计的中间语言 <a class="header-anchor" href="#本体是可审计的中间语言" aria-label="Permalink to &quot;本体是可审计的中间语言&quot;">​</a></h3><p>计划 JSON 比公式树更适合研究日志：研究员能读 \\(p\\)，能反对某一维（「不要再搜放量确认」），而不必读生成代码。这与 Alpha-GPT 的反编译同目标，但 AlphaSchema 把中间语言当成搜索原语，而不是事后解释。人闸门可以加在计划层：未批准的事件类型不得进入实现预算。这比在夏普表上做闸门更早、更便宜。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>词表是偏见。A 股实验不能直接当美股本体；涨跌停、T+1、集合竞价会改变「突破」的语义，必须成为 Context 的合法取值，否则计划在合同上不可交易。公开信息对完整词表规模、奖励精确公式与宇宙过滤以论文附录与仓库为准；新闻稿级「研究进展」不计入方法。不同 LLM 实现质量相近，不意味着 \\(\\Gamma\\) 方差为零，只意味着相对计划选择为二阶。</p><p>不要把语义计划自动当成可交易策略。实现仍可能泄漏、仍可能不可执行、仍可能只有等权微盘上的 t。搜索预算记入 \\(N\\)。不要在计划层声称发现了新经济学：五元组是工程本体，不是资产定价的充分统计量。系统出口是计划与因子实现，不是订单；配额选择优化的是回测预算，不是市场冲击。</p><p><span class="marginnote">出处：Yi et al., <em>AlphaSchema</em>, arXiv:2607.26642。对照 Wang et al., <em>Alpha-GPT</em>；Shi et al., <em>Hubble</em>；Liu et al., <em>XAlpha</em>。评价：McLean–Pontiff, <em>JF</em>, 2016；Hou–Xue–Zhang, <em>RFS</em>, 2020。替代模型见 Ke 等人 LightGBM 一类梯度提升；此处仅作语义空间上的回归器。</span></p>',26)),(t(),s(E,null,{default:l(()=>[m(i,{id:"mermaid-100",class:"mermaid",graph:"flowchart%20TD%0A%20%20VOCAB%5B%22%E8%AF%8D%E8%A1%A8%EF%BC%9AEvent%2FContext%2FQualities%2FDirection%2FOutput%22%5D%20--%3E%20SAMPLE%5B%22%E5%80%99%E9%80%89%E8%AE%A1%E5%88%92%E6%B1%A0%22%5D%0A%20%20SURR%5B%22%E8%AF%AD%E4%B9%89%E6%9B%BF%E4%BB%A3%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20QUOTA%5B%22%E9%85%8D%E9%A2%9D%EF%BC%9A%E6%8E%A2%E7%B4%A2%20%2F%20%E5%88%A9%E7%94%A8%20%2F%20%E5%8F%98%E5%BC%82%22%5D%0A%20%20SAMPLE%20--%3E%20QUOTA%0A%20%20QUOTA%20--%3E%20P%5B%22%E9%80%89%E4%B8%AD%E7%9A%84%20p%22%5D%0A%20%20P%20--%3E%20LLM%5B%22LLM%20%E5%AE%9E%E7%8E%B0%20%CE%93(p)%22%5D%0A%20%20LLM%20--%3E%20GUARD%5B%22%E6%B3%84%E6%BC%8F%E4%B8%8E%E5%90%88%E5%90%8C%E5%AE%88%E5%8D%AB%22%5D%0A%20%20GUARD%20--%3E%20J%5B%22%E5%9B%9E%E6%B5%8B%E5%A5%96%E5%8A%B1%20J%22%5D%0A%20%20J%20--%3E%20BUF%5B%22%E8%AE%A1%E5%88%92-%E5%A5%96%E5%8A%B1%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20SURR%0A%20%20P%20--%3E%20LOG%5B%22%E5%8F%AF%E5%AE%A1%E8%AE%A1%20JSON%20%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[n("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"AlphaSchema 用五元组语义计划当搜索原语，把「搜什么」与「如何实现」分开。"),a("li",null,"奖励记在计划上，替代模型加配额分配实现预算；LLM 主要当实现器。"),a("li",null,"词表即本体，也即偏见；已知异常应标进空间以免高效再发现拥挤模板。"),a("li",null,"同一计划跨模型实现质量相近，支持瓶颈在语义选择；主结果仍应固定实现器。"),a("li",null,"计划可审计、可被人闸门拦截，仍须过加权、成本与样本外，才能谈经济显著。"),a("li",null,"出处：Yi et al., arXiv:2607.26642；对照 Alpha-GPT、Hubble、XAlpha；评价见 McLean–Pontiff 与 Hou–Xue–Zhang。")],-1))])}const b=o(A,[["render",c]]);export{P as __pageData,b as default};
